package rig;
import com.etheller.warsmash.viewer5.handlers.w3x.simulation.CUnit;
import com.etheller.warsmash.viewer5.handlers.w3x.War3MapViewer;
/** Loads the map and lets it run ($FRAMES frames, 300 by default): the map loads, its scripts start, the simulation ticks. */
public class Idle extends Scenario {
  static final int FRAMES = Integer.parseInt(System.getenv().getOrDefault("FRAMES", "300"));
  boolean wasShown;
  public boolean frame(War3MapViewer v, int n) {
    if (n % 100 == 0) { String count = ""; String types = System.getenv("COUNT"); if (types != null) for (String t : types.split(",")) { int k = 0; java.util.Map<Integer, Integer> owners = new java.util.TreeMap<>(); for (CUnit u : v.simulation.getUnits()) if (u.getTypeId().toString().equals(t) && !u.isDead()) { k++; owners.merge(u.getPlayerIndex(), 1, Integer::sum); } count += " " + t + "=" + k + (owners.size() > 0 ? owners.toString() : ""); } System.err.println("RIG: tick " + v.simulation.getGameTurnTick() + " units " + v.simulation.getUnits().size() + count); }
    com.etheller.warsmash.viewer5.handlers.w3x.ui.CineFilter f = null; try { var fld = com.etheller.warsmash.WarsmashGdxMapScreen.class.getDeclaredField("minimapUI"); fld.setAccessible(true); var ui = (com.etheller.warsmash.viewer5.handlers.w3x.ui.MeleeUI) fld.get(Main.mapScreen); f = ui == null ? null : ui.getCineFilter(); } catch (Exception e) { }
    if (n == 50) System.err.println("RIG: cine filter object " + f);
    if (n == 1 && System.getenv("RNGLOG") != null) { try { final var sim = v.simulation; final java.io.PrintWriter pw = new java.io.PrintWriter(new java.io.FileWriter(System.getenv("RNGLOG"))); var rf = com.etheller.warsmash.viewer5.handlers.w3x.simulation.CSimulation.class.getDeclaredField("seededRandom"); rf.setAccessible(true);
      java.util.Random logging = new java.util.Random(1337L) { @Override protected int next(int bits) { int r = super.next(bits); StackTraceElement[] st = new Throwable().getStackTrace(); StringBuilder b = new StringBuilder("t" + sim.getGameTurnTick() + " " + r); int k = 0; for (StackTraceElement e : st) { if (e.getClassName().startsWith("java.util.Random") || e.getClassName().startsWith("rig.")) continue; b.append(' ').append(e.getClassName().substring(e.getClassName().lastIndexOf('.') + 1)).append('.').append(e.getMethodName()).append(':').append(e.getLineNumber()); if (++k == 4) break; } pw.println(b); pw.flush(); return r; } };
      rf.set(sim, logging); System.err.println("RIG: random logging on"); } catch (Throwable t) { System.err.println("RIG: random logging failed " + t); } }
    if (System.getenv("DUMPTICK") != null && v.simulation.getGameTurnTick() == Integer.parseInt(System.getenv("DUMPTICK"))) { StringBuilder sb = new StringBuilder(); for (CUnit u : v.simulation.getUnits()) sb.append("RIG: U ").append(u.getHandleId()).append(' ').append(u.getTypeId()).append(" o").append(u.getPlayerIndex()).append(' ').append(u.getX()).append(',').append(u.getY()).append(" life ").append(u.getLife()).append(" mana ").append(u.getMana()).append(' ').append(u.getCurrentBehavior() == null ? "-" : u.getCurrentBehavior().getClass().getSimpleName()).append('\n'); System.err.print(sb); }
    if (System.getenv("HASH") != null) { long h = 1125899906842597L; for (CUnit u : v.simulation.getUnits()) { h = 31 * h + u.getHandleId(); h = 31 * h + u.getTypeId().getValue(); h = 31 * h + u.getPlayerIndex(); h = 31 * h + Float.floatToIntBits(u.getX()); h = 31 * h + Float.floatToIntBits(u.getY()); h = 31 * h + Float.floatToIntBits(u.getLife()); h = 31 * h + Float.floatToIntBits(u.getMana()); } for (int i = 0; i < 12; i++) { h = 31 * h + v.simulation.getPlayer(i).getGold(); h = 31 * h + v.simulation.getPlayer(i).getLumber(); } System.err.println("RIG: H " + v.simulation.getGameTurnTick() + " " + v.simulation.getUnits().size() + " " + h); }
    // KILL=frame:type kills one living unit of that type then, by the first hero of player 1 (a house in Human 06).
    // MOVETO=frame:x,y puts player 2's first hero (index 1) at the point then.
    String moveTo = System.getenv("MOVETO"); if (moveTo != null && n == Integer.parseInt(moveTo.split(":")[0])) { String[] xy = moveTo.split(":")[1].split(","); for (CUnit u : v.simulation.getPlayerHeroes(Integer.parseInt(System.getenv().getOrDefault("MOVEPLAYER", "1")))) { u.setPointAndCheckUnstuck(Float.parseFloat(xy[0]), Float.parseFloat(xy[1]), v.simulation); System.err.println("RIG: moved " + u.getTypeId() + " to " + (int) u.getX() + "," + (int) u.getY()); break; } }
    String kill = System.getenv("KILL"); if (kill != null && n == Integer.parseInt(kill.split(":")[0])) { CUnit killer = null; for (CUnit u : v.simulation.getPlayerHeroes(1)) killer = u; for (CUnit u : v.simulation.getUnits()) if (u.getTypeId().toString().equals(kill.split(":")[1]) && !u.isDead()) { u.damage(v.simulation, killer, false, false, com.etheller.warsmash.viewer5.handlers.w3x.simulation.combat.CAttackType.CHAOS, com.etheller.warsmash.viewer5.handlers.w3x.simulation.trigger.enumtypes.CDamageType.UNIVERSAL, "WHOKNOWS", 99999f); System.err.println("RIG: killed " + u.getTypeId() + " dead=" + u.isDead() + " by " + killer); break; } }
    boolean shown = f != null && f.isDisplayed();
    if (shown != wasShown) { System.err.println("RIG: cine filter " + (shown ? "shown" : "hidden") + " at tick " + v.simulation.getGameTurnTick()); wasShown = shown; }
    if (n == FRAMES - 30 || n == FRAMES) { try { var fld = com.etheller.warsmash.WarsmashGdxMapScreen.class.getDeclaredField("minimapUI"); fld.setAccessible(true); var ui = (com.etheller.warsmash.viewer5.handlers.w3x.ui.MeleeUI) fld.get(Main.mapScreen); var d = ui.getQuestDialog(); if (n == FRAMES - 30) { d.setVisible(true); } else { var root = (com.etheller.warsmash.parsers.fdf.GameUI) v.getGameUI(); var t = (com.etheller.warsmash.parsers.fdf.frames.StringFrame) root.getFrameByName("QuestDetailsTitle", 0); System.err.println("RIG: quest dialog visible=" + d.isVisible() + " details title=" + (t == null ? "-" : t.getText())); } } catch (Throwable e) { System.err.println("RIG: quest dialog EXC " + e); e.printStackTrace(); } }
    if (System.getenv("DRAIN") != null && n == FRAMES / 2) { v.simulation.getPlayer(3).setGold(100); System.err.println("RIG: drained player 3 gold to 100"); }
    if (System.getenv("DRAIN") != null && n == FRAMES / 2 + 5) System.err.println("RIG: player 3 gold 5 frames later " + v.simulation.getPlayer(3).getGold());
    if (n == FRAMES - 20) { try { var fld = com.etheller.warsmash.WarsmashGdxMapScreen.class.getDeclaredField("minimapUI"); fld.setAccessible(true); var ui = (com.etheller.warsmash.viewer5.handlers.w3x.ui.MeleeUI) fld.get(Main.mapScreen); var m = com.etheller.warsmash.viewer5.handlers.w3x.ui.MeleeUI.class.getDeclaredMethod("approachQuestVillager", CUnit.class); m.setAccessible(true); int marked = 0; String r = ""; for (CUnit u : new java.util.ArrayList<>(v.simulation.getUnits())) if (v.hasQuestDialogueMarker(u)) { marked++; if (r.isEmpty()) { boolean ok = (Boolean) m.invoke(ui, u); r = " tapping " + u.getUnitType().getName() + ": hero sent=" + ok; } } System.err.println("RIG: quest villagers marked=" + marked + r); } catch (Throwable e) { System.err.println("RIG: villager check " + e); } }
    if (n == FRAMES) { StringBuilder pg = new StringBuilder("RIG: player gold/lumber"); for (int i = 0; i < 12; i++) pg.append(' ').append(i).append('=').append(v.simulation.getPlayer(i).getGold()).append('/').append(v.simulation.getPlayer(i).getLumber()); System.err.println(pg); }
    if (n == FRAMES) { for (var q : v.simulation.getQuestLog().getQuests()) { StringBuilder b = new StringBuilder("RIG: quest " + q.getTitle() + " required=" + q.isRequired() + " discovered=" + q.isDiscovered() + " completed=" + q.isCompleted() + " items:"); for (var i : q.getItems()) b.append(" [").append(i.getDescription()).append(i.isCompleted() ? " done" : "").append(']'); System.err.println(b); } }
    String dump = System.getenv("DUMPTYPE"); if (dump != null && n == FRAMES - 1) for (CUnit u : v.simulation.getUnits()) if (u.getTypeId().toString().equals(dump)) { StringBuilder b = new StringBuilder("RIG: " + dump + " " + u.getHandleId() + " level " + (u.getHeroData() == null ? -1 : u.getHeroData().getHeroLevel()) + " sp " + (u.getHeroData() == null ? -1 : u.getHeroData().getSkillPoints()) + " behavior " + u.getCurrentBehavior() + " mana " + u.getMana() + " abilities:"); for (var a : u.getAbilities()) b.append(' ').append(a.getAlias()).append('/').append(a.getClass().getSimpleName()).append(a instanceof com.etheller.warsmash.viewer5.handlers.w3x.simulation.abilities.generic.AbstractGenericSingleIconActiveAbility g ? "L" + g.getLevel() : ""); System.err.println(b); }
    if (dump != null && n == Integer.parseInt(System.getenv().getOrDefault("CHECKAT", String.valueOf(FRAMES - 1)))) for (CUnit u : v.simulation.getUnits()) if (u.getTypeId().toString().equals(dump)) {
      com.etheller.warsmash.viewer5.handlers.w3x.simulation.abilities.CAbility sk = null; for (var a : u.getAbilities()) if (a.getAlias().toString().equals("SNdc")) sk = a;
      CUnit near = null; for (CUnit w : v.simulation.getUnits()) if (w.getTypeId().toString().startsWith("nC0") && !w.isDead() && (near == null || w.distance(u) < near.distance(u))) near = w;
      if (sk == null || near == null) { System.err.println("RIG: check none " + sk + " " + near); break; }
      StringBuilder why = new StringBuilder("RIG: check villager " + near.getTypeId() + " race " + v.simulation.getUnitData().getRaceName(near.getTypeId()) + " owner " + near.getPlayerIndex() + " dist " + (int) near.distance(u) + " hidden caster " + u.isHidden() + ":");
      Object rec = java.lang.reflect.Proxy.newProxyInstance(Idle.class.getClassLoader(), new Class<?>[]{com.etheller.warsmash.viewer5.handlers.w3x.simulation.util.AbilityActivationReceiver.class}, (pr, mm, aa) -> { why.append(" use:").append(mm.getName()).append(java.util.Arrays.toString(aa)); return null; });
      int oid = com.etheller.warsmash.viewer5.handlers.w3x.simulation.orders.OrderIds.darkconversion;
      sk.checkCanUse(v.simulation, u, oid, (com.etheller.warsmash.viewer5.handlers.w3x.simulation.util.AbilityActivationReceiver) rec);
      Object trec = java.lang.reflect.Proxy.newProxyInstance(Idle.class.getClassLoader(), new Class<?>[]{com.etheller.warsmash.viewer5.handlers.w3x.simulation.util.AbilityTargetCheckReceiver.class}, (pr, mm, aa) -> { why.append(" target:").append(mm.getName()).append(java.util.Arrays.toString(aa)); return null; });
      sk.checkCanTarget(v.simulation, u, oid, near, (com.etheller.warsmash.viewer5.handlers.w3x.simulation.util.AbilityTargetCheckReceiver) trec);
      why.append(" order accepted=").append(u.order(v.simulation, oid, near)).append(" behavior after ").append(u.getCurrentBehavior());
      System.err.println(why); break; }
    String trace = System.getenv("TRACETYPE"); if (trace != null && n % 10 == 0) for (CUnit u : v.simulation.getUnits()) if (u.getTypeId().toString().equals(trace)) {
      CUnit near = null; for (CUnit w : v.simulation.getUnits()) if ((w.getTypeId().toString().startsWith("nC0") || w.getTypeId().toString().equals("nzom")) && (near == null || w.distance(u) < near.distance(u))) near = w;
      StringBuilder b = new StringBuilder(); if (near != null) for (var a : near.getAbilities()) if (a instanceof com.etheller.warsmash.viewer5.handlers.w3x.simulation.abilities.generic.CBuff) b.append(a.getAlias()).append(' ');
      System.err.println("RIG: trace f" + n + " " + trace + " " + u.getHandleId() + " " + (u.getCurrentBehavior() == null ? null : u.getCurrentBehavior().getClass().getSimpleName()) + " order " + (u.getCurrentOrder() == null ? null : u.getCurrentOrder().getOrderId()) + " near " + (near == null ? "-" : near.getTypeId() + " " + near.getHandleId() + " dead=" + near.isDead() + " d=" + (int) near.distance(u) + " owner " + near.getPlayerIndex() + " buffs " + b)); }
    return n >= FRAMES;
  }
}
